source(file.path(dirname(sub("--file=", "", grep("--file=", commandArgs(), value = TRUE))), "common.R"))
ch <- grpc_channel(URL)
cat("## A: GOAWAY mid-stream, then stream continues and ends OK on server\n")
s <- scn(ch, "h,m1,g,s300,m1,t0"); for (i in 1:4) show(paste("next", i), s$next_message()); state(s); show("call after", grpc_call(ch, M, raw())$message); snew()
cat("## B: server closes connection mid-stream after 2 messages\n")
s <- scn(ch, "h,m2,s300,c"); for (i in 1:5) show(paste("next", i), s$next_message()); state(s); show("call after", grpc_call(ch, M, raw())$message); snew()
cat("## B2: server closes immediately after 2 messages (same read)\n")
s <- scn(ch, "h,m2,c"); Sys.sleep(.3); for (i in 1:5) show(paste("next", i), s$next_message()); state(s); snew()
cat("## C: cancel after the body fully arrived (trailers sent) with 2 unread\n")
s <- scn(ch, "h,m3,t0"); show("next", s$next_message()); Sys.sleep(.3); s$cancel(); for (i in 1:2) show("next", s$next_message()); state(s); show("status", s$status()); snew()
cat("## D: details cache: decode twice, and in a forked child\n")
e1 <- tryCatch(grpc_call(ch, M, raw(), metadata = c("x-scn" = "h,V5")), error = identity); str(e1$details)
cat("cached pool class:", class(zugrpc:::rpc_env$pool), "\n")
e2 <- tryCatch(grpc_call(ch, M, raw(), metadata = c("x-scn" = "h,V5")), error = identity); cat("identical details:", identical(e1$details, e2$details), "\n")
r <- parallel::mccollect(parallel::mcparallel({ e <- tryCatch(grpc_call(ch, M, raw(), metadata = c("x-scn" = "h,V5")), error = identity, warning = identity); list(class(e)[1], e$details) }))[[1]]; str(r)
cat("## E: poisoned cache (hostile session): rpc_env$pool replaced\n")
assign("pool", "junk", envir = zugrpc:::rpc_env); e <- withCallingHandlers(tryCatch(grpc_call(ch, M, raw(), metadata = c("x-scn" = "h,V5")), error = identity), warning = function(w) { cat("   warning:", class(w)[1], "\n"); invokeRestart("muffleWarning") }); cat(class(e)[1], "details NULL:", is.null(e$details), "\n")
cat("## F: process exits with one open stream and an idle conn (see server log after)\n")
s <- scn(ch, "h,m1,w"); invisible(s$next_message())
